@@ -0,0 +1,18 @@
+'use strict';
+
+/**
+ * Regex that matches a Telegram bot token embedded in a URL or plain string.
+ * Format: <digits>:<35-char alphanumeric+_- string>
+ * e.g. https://api.telegram.org/bot123456789:AABBccDDeeFFggHHiiJJkkLLmmNNoo1234567/sendMessage
+ */
+const TELEGRAM_TOKEN_RE = /\b(\d{8,10}:[A-Za-z0-9_-]{35})\b/g;
+
+/**
+ * Replace any Telegram bot tokens found in `str` with `[REDACTED]`.
+ *
+ * @param {string} str
+ * @returns {string}
+ */
+function redactToken(str) {
+  if (typeof str !== 'string') return str;
+  return str.replace(TELEGRAM_TOKEN_RE, '[REDACTED]');
+}
+
+module.exports = { redactToken };
--- a/src/error.js
