@@ -0,0 +1,30 @@
+'use strict';
+
+const { redactToken } = require('./utils/redact');
+
+/**
+ * Wraps an error so that its message and stack trace have any embedded
+ * Telegram bot tokens replaced with [REDACTED] before the error is
+ * propagated or logged.
+ *
+ * @param {Error} err  Original error
+ * @returns {Error}    The same error object, mutated in-place
+ */
+function sanitizeError(err) {
+  if (!(err instanceof Error)) return err;
+
+  if (typeof err.message === 'string') {
+    // message is normally read-only on V8; use defineProperty to override
+    try {
+      Object.defineProperty(err, 'message', {
+        value: redactToken(err.message),
+        writable: true,
+        configurable: true,
+      });
+    } catch (_) {
+      // best-effort
+    }
+  }
+
+  if (typeof err.stack === 'string') {
+    err.stack = redactToken(err.stack);
+  }
+
+  return err;
+}
+
+module.exports = { sanitizeError };
