+import { Context, Next } from "hono";
+import { lookup } from "dns/promises";
+
+// Private/reserved IP ranges that should be blocked for SSRF prevention
+const BLOCKED_IP_RANGES = [
+  // Loopback
+  /^127\./,
+  /^::1$/,
+  // Private networks
+  /^10\./,
+  /^172\.(1[6-9]|2[0-9]|3[01])\./,
+  /^192\.168\./,
+  // Link-local (AWS metadata, etc.)
+  /^169\.254\./,
+  /^fe80:/i,
+  // Other reserved
+  /^0\./,
+  /^100\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\./,
+  /^198\.51\.100\./,
+  /^203\.0\.113\./,
+  /^224\./,
+  /^240\./,
+  /^255\.255\.255\.255$/,
+  // IPv6 private
+  /^fc00:/i,
+  /^fd/i,
+];
+
+const BLOCKED_HOSTNAMES = [
+  "localhost",
+  "metadata.google.internal",
+];
+
+function isPrivateIP(ip: string): boolean {
+  return BLOCKED_IP_RANGES.some((range) => range.test(ip));
+}
+
+function isBlockedHostname(hostname: string): boolean {
+  const lower = hostname.toLowerCase();
+  return BLOCKED_HOSTNAMES.some((blocked) => lower === blocked || lower.endsWith(`.${blocked}`));
+}
+
+export async function isSSRFSafeUrl(urlString: string): Promise<boolean> {
+  let parsedUrl: URL;
+  try {
+    parsedUrl = new URL(urlString);
+  } catch {
+    return false;
+  }
+
+  const hostname = parsedUrl.hostname;
+
+  // Block if hostname is directly a private IP
+  if (isPrivateIP(hostname)) {
+    return false;
+  }
+
+  // Block known bad hostnames
+  if (isBlockedHostname(hostname)) {
+    return false;
+  }
+
+  // Resolve hostname to IP and check if it resolves to a private address
+  try {
+    const result = await lookup(hostname, { all: true });
+    const addresses = Array.isArray(result) ? result : [result];
+    for (const addr of addresses) {
+      if (isPrivateIP(addr.address)) {
+        return false;
+      }
+    }
+  } catch {
+    // If DNS resolution fails, block the request to be safe
+    return false;
+  }
+
+  return true;
+}

