+export function sanitizeBlockEditorContent(content: Record<string, any>): Record<string, any> {
+	if (!content || typeof content !== 'object') return content;
+
+	if (Array.isArray(content)) {
+		return content.map((item) => sanitizeBlockEditorContent(item));
+	}
+
+	const sanitized: Record<string, any> = {};
+
+	for (const [key, value] of Object.entries(content)) {
+		if (typeof value === 'string') {
+			// Sanitize any string that might contain HTML
+			sanitized[key] = sanitizeHtml(value, defaultOptions);
+		} else if (typeof value === 'object' && value !== null) {
+			sanitized[key] = sanitizeBlockEditorContent(value);
+		} else {
+			sanitized[key] = value;
+		}
+	}
+
+	return sanitized;
+}

