+/**
+ * Utilities for checking if an IP address or hostname resolves to a private
+ * or reserved address, to prevent SSRF attacks.
+ */
+
+/**
+ * Checks if a given hostname resolves to a private or reserved IP address.
+ * Returns true if the address is private/reserved (and thus should be blocked).
+ */
+export async function isPrivateAddress(hostname: string): Promise<boolean> {
+  // Check if it's already an IP address
+  if (isIPv4(hostname)) {
+    return isPrivateIPv4(hostname);
+  }
+  if (isIPv6(hostname)) {
+    return isPrivateIPv6(hostname);
+  }
+
+  // It's a hostname; resolve it
+  try {
+    const addresses = await resolveHostname(hostname);
+    for (const addr of addresses) {
+      if (isIPv4(addr)) {
+        if (isPrivateIPv4(addr)) return true;
+      } else if (isIPv6(addr)) {
+        if (isPrivateIPv6(addr)) return true;
+      }
+    }
+    return false;
+  } catch {
+    // If we can't resolve, treat as private to be safe
+    return true;
+  }
+}
+
+function isIPv4(addr: string): boolean {
+  return /^(\d{1,3}\.){3}\d{1,3}$/.test(addr);
+}
+
+function isIPv6(addr: string): boolean {
+  // Basic IPv6 detection
+  return addr.includes(":");
+}
