+      const results: string[] = [];
+      try {
+        const aRecords = await Deno.resolveDns(hostname, "A");
+        results.push(...aRecords);
+      } catch {
+        // ignore
+      }
+      try {
+        const aaaaRecords = await Deno.resolveDns(hostname, "AAAA");
+        results.push(...aaaaRecords);
+      } catch {
+        // ignore
+      }
+      if (results.length > 0) return results;
+    } catch {
+      // fall through
+    }
+  }
