 // Formatting utilities for IRC messages

+/**
+ * Strip the Matrix reply fallback from a message body.
+ * Matrix replies include a fallback block at the start of the body:
+ *   > <sender> original message
+ *   >
+ *
+ *   actual reply text
+ *
+ * This function removes that fallback to prevent leaking message content.
+ */
+export function stripReplyFallback(body: string): string {
+    // The fallback consists of lines starting with "> " or ">", followed by a blank line
+    const lines = body.split('\n');
+    let i = 0;
+    while (i < lines.length && lines[i].startsWith('>')) {
+        i++;
+    }
+    // Skip the blank line after the fallback
+    if (i < lines.length && lines[i].trim() === '') {
+        i++;
+    }
+    return lines.slice(i).join('\n');
+}

