+/**
+ * Sanitize a value to be safe for use in IRC commands.
+ * IRC uses \r\n as command delimiters, so we must strip these
+ * to prevent command injection.
+ * @param value The value to sanitize
+ * @returns The sanitized value with CR and LF characters removed
+ */
+export function sanitizeIrcValue(value: string): string {
+    // Remove carriage returns and newlines to prevent IRC command injection
+    return value.replace(/[\r\n]/g, "");
+}
+
+/**
+ * Validate that a value does not contain IRC command injection characters.
+ * @param value The value to validate
+ * @returns true if the value is safe, false otherwise
+ */
+export function isValidIrcValue(value: string): boolean {
+    return !/[\r\n]/.test(value);
+}
