+ * Validates the CSRF token for the given request.
+ * Returns true if the request is valid (passes CSRF check), false otherwise.
+ *
+ * The check compares the Origin/Referer header against the target origin.
+ * This is a standard "same-origin" CSRF mitigation technique.
+ */
+export function validateCsrf(serverRequestEv: ServerRequestEvent, opts?: { checkOrigin?: boolean }): boolean {
+  if (opts?.checkOrigin === false) {
+    return true;
+  }
+
+  const { request } = serverRequestEv;
+  const url = new URL(request.url);
+  const targetOrigin = url.origin;
+
+  // Check Origin header first
+  const originHeader = request.headers.get('origin');
+  if (originHeader) {
+    return originHeader === targetOrigin;
+  }
+
+  // Fall back to Referer header
+  const refererHeader = request.headers.get('referer');
+  if (refererHeader) {
+    try {
+      const refererUrl = new URL(refererHeader);
+      return refererUrl.origin === targetOrigin;
+    } catch {
+      return false;
+    }
+  }
+
+  // If neither Origin nor Referer is present, deny by default for safety
+  return false;
+}
