+/**
+ * Sanitizes a CSS value to prevent CSS injection attacks.
+ * Removes characters that could be used to break out of a CSS property value
+ * and inject arbitrary CSS rules.
+ *
+ * @param value - The CSS value to sanitize
+ * @returns The sanitized CSS value
+ */
+export const sanitizeCssValue = (value: string | undefined): string => {
+  if (value === undefined || value === null) {
+    return '';
+  }
+  // Remove characters that can be used to escape a CSS value context
+  return String(value).replace(/[{};<>]/g, '');
+};
