+/**
+ * Sanitizes a filesystem path for safe embedding in LLM prompts.
+ *
+ * Strips Unicode control characters, format characters, bidirectional
+ * override/isolate markers, zero-width characters, and line/paragraph
+ * separators that could be used for prompt injection via crafted
+ * directory names (CVE-2026-27001).
+ */
+export function sanitizePathForPrompt(path: string): string {
+  // Remove characters in the following Unicode categories / ranges:
+  //   - C0 controls (U+0000–U+001F) except we keep nothing; all stripped
+  //   - DEL (U+007F)
+  //   - C1 controls (U+0080–U+009F)
+  //   - Unicode format characters (category Cf): includes bidi overrides,
+  //     zero-width joiners/non-joiners, word joiners, soft hyphens, etc.
+  //     Ranges: U+00AD, U+0600–U+0605, U+061C, U+06DD, U+070F, U+08E2,
+  //             U+180E, U+200B–U+200F, U+202A–U+202E, U+2060–U+2064,
+  //             U+2066–U+206F, U+FEFF, U+FFF9–U+FFFB, U+110BD, U+110CD,
+  //             U+13430–U+13438, U+1BCA0–U+1BCA3, U+1D173–U+1D17A,
+  //             U+E0001, U+E0020–U+E007F
+  //   - Line separator (U+2028) and paragraph separator (U+2029)
+  //   - Newlines and carriage returns (\n \r)
+  // eslint-disable-next-line no-control-regex
+  return path.replace(
+    /[\u0000-\u001F\u007F\u0080-\u009F\u00AD\u0600-\u0605\u061C\u06DD\u070F\u08E2\u180E\u200B-\u200F\u202A-\u202E\u2028\u2029\u2060-\u2064\u2066-\u206F\uFEFF\uFFF9-\uFFFB]/g,
+    ''
+  );
+}
