+'use strict';
+
+/**
+ * CSRF-style guard for the browser control plane.
+ *
+ * Mutating HTTP methods (POST, PUT, PATCH, DELETE) are rejected when the
+ * request indicates a non-loopback Origin or Referer, or when the browser
+ * sends `Sec-Fetch-Site: cross-site`.
+ *
+ * Loopback origins that are considered safe:
+ *   - No Origin/Referer header at all (e.g. curl, native clients)
+ *   - Origin: null  (some browser edge-cases – treated as safe for localhost)
+ *   - Any origin whose hostname resolves to 127.x, ::1, or "localhost"
+ */
+
+const MUTATING_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
+
+const LOOPBACK_HOSTNAMES = new Set(['localhost', '127.0.0.1', '::1', '[::1]']);
+
+function isLoopbackHost(hostname) {
+  if (!hostname) return false;
+  // Strip port
+  const host = hostname.replace(/:\d+$/, '').toLowerCase();
+  if (LOOPBACK_HOSTNAMES.has(host)) return true;
+  // 127.0.0.0/8
+  if (/^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(host)) return true;
+  return false;
+}
+
+function extractHostname(urlString) {
+  try {
+    return new URL(urlString).hostname;
+  } catch (_) {
+    return null;
+  }
+}
+
+/**
+ * Express/Connect-compatible middleware.
+ */
+function csrfGuard(req, res, next) {
+  if (!MUTATING_METHODS.has(req.method && req.method.toUpperCase())) {
+    return next();
+  }
+
+  // Sec-Fetch-Site is the most reliable signal in modern browsers.
+  const secFetchSite = req.headers['sec-fetch-site'];
+  if (secFetchSite && secFetchSite === 'cross-site') {
+    return res.status(403).json({ error: 'Forbidden: cross-site request rejected' });
+  }
+
+  // Fall back to Origin / Referer validation.
+  const origin = req.headers['origin'];
+  const referer = req.headers['referer'];
+
+  const checkUrl = origin || referer;
+  if (checkUrl && checkUrl !== 'null') {
+    const hostname = extractHostname(checkUrl);
+    if (!isLoopbackHost(hostname)) {
+      return res.status(403).json({ error: 'Forbidden: cross-origin request rejected' });
+    }
+  }
+
+  return next();
+}
+
+module.exports = csrfGuard;
