+'use strict';
+
+const csrfGuard = require('../src/server/middleware/csrf');
+
+function makeReq(method, headers) {
+  return { method, headers: headers || {} };
+}
+
+function makeRes() {
+  const res = {
+    _status: null,
+    _body: null,
+    status(code) { this._status = code; return this; },
+    json(body) { this._body = body; return this; },
+  };
+  return res;
+}
+
+describe('csrfGuard middleware', () => {
+  test('allows GET requests unconditionally', () => {
+    const req = makeReq('GET', { origin: 'https://evil.example.com' });
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(true);
+    expect(res._status).toBeNull();
+  });
+
+  test('allows POST with no Origin/Referer (native client)', () => {
+    const req = makeReq('POST', {});
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(true);
+  });
+
+  test('allows POST from localhost origin', () => {
+    const req = makeReq('POST', { origin: 'http://localhost:9222' });
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(true);
+  });
+
+  test('allows POST from 127.0.0.1 origin', () => {
+    const req = makeReq('POST', { origin: 'http://127.0.0.1:9222' });
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(true);
+  });
+
+  test('blocks POST from cross-site origin', () => {
+    const req = makeReq('POST', { origin: 'https://evil.example.com' });
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(false);
+    expect(res._status).toBe(403);
+  });
+
+  test('blocks DELETE from cross-site referer', () => {
+    const req = makeReq('DELETE', { referer: 'https://evil.example.com/page' });
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(false);
+    expect(res._status).toBe(403);
+  });
+
+  test('blocks POST when Sec-Fetch-Site is cross-site', () => {
+    const req = makeReq('POST', { 'sec-fetch-site': 'cross-site' });
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(false);
+    expect(res._status).toBe(403);
+  });
+
+  test('allows POST when Sec-Fetch-Site is same-origin', () => {
+    const req = makeReq('POST', { 'sec-fetch-site': 'same-origin' });
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(true);
+  });
+
+  test('blocks PUT from cross-site origin', () => {
+    const req = makeReq('PUT', { origin: 'http://attacker.test' });
+    const res = makeRes();
+    let called = false;
+    csrfGuard(req, res, () => { called = true; });
+    expect(called).toBe(false);
+    expect(res._status).toBe(403);
+  });
+});

