@@ -0,0 +1,60 @@
+import { IncomingMessage, ServerResponse } from "http";
+
+/**
+ * Checks if a Host header value refers to localhost.
+ * Accepts:
+ *   - localhost
+ *   - 127.x.x.x
+ *   - ::1
+ *   - [::1]
+ * With optional port suffix.
+ */
+export function isLocalhostHost(host: string): boolean {
+  // Strip port
+  const hostname = host.replace(/:\d+$/, "").toLowerCase();
+
+  if (hostname === "localhost") {
+    return true;
+  }
+
+  // IPv4 loopback: 127.0.0.0/8
+  if (/^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(hostname)) {
+    return true;
+  }
+
+  // IPv6 loopback
+  if (hostname === "::1" || hostname === "[::1]") {
+    return true;
+  }
+
+  return false;
+}
+
+/**
+ * Express/Connect-compatible middleware that validates the Host header
+ * to prevent DNS rebinding attacks.
+ *
+ * Only allows requests where the Host header refers to localhost or
+ * a loopback address.
+ *
+ * Usage:
+ *   app.use(hostHeaderValidation());
+ */
+export function hostHeaderValidation() {
+  return function dnsRebindingProtectionMiddleware(
+    req: IncomingMessage & { headers: Record<string, string | string[] | undefined> },
+    res: ServerResponse,
+    next: (err?: unknown) => void
+  ): void {
+    const hostHeader = req.headers["host"];
+
+    if (!hostHeader || typeof hostHeader !== "string") {
+      res.writeHead(403, { "Content-Type": "application/json" });
+      res.end(
+        JSON.stringify({ error: "Forbidden: Missing or invalid Host header. DNS rebinding protection is enabled." })
+      );
+      return;
+    }
+
+    if (!isLocalhostHost(hostHeader)) {
+      res.writeHead(403, { "Content-Type": "application/json" });
+      res.end(
+        JSON.stringify({ error: "Forbidden: Invalid Host header. DNS rebinding protection is enabled." })
+      );
+      return;
+    }
+
+    next();
+  };
+}

