+/**
+ * Server-side utility to retrieve a valid access token from the session.
+ * Use this instead of reading accessToken from loader data to avoid
+ * exposing the token in the page HTML.
+ */
+export async function getAccessToken(args: LoaderFunctionArgs): Promise<string | null> {
+  const { request } = args;
+  const session = await getSession(request.headers.get('Cookie'));
+
+  const accessToken = session.get('accessToken');
+  const sealedSession = session.get('sealedSession');
+
+  if (!accessToken) {
+    return null;
+  }
+
+  // Check if the token needs to be refreshed
+  try {
+    const refreshed = await refreshSession(sealedSession);
+    if (refreshed) {
+      return refreshed.accessToken;
+    }
+  } catch {
+    // If refresh fails, return the existing token
+  }
+
+  return accessToken;
+}
