+import * as t from '@babel/types';
+
+/**
+ * Checks whether a node is a "constant" expression that is safe to evaluate.
+ * Only allows literals, basic arithmetic/string operations, and arrays of the same.
+ * Disallows identifiers, function calls, member expressions, etc.
+ */
+export function isConstantExpression(node: t.Node): boolean {
+    if (t.isStringLiteral(node) || t.isNumericLiteral(node) || t.isBooleanLiteral(node) || t.isNullLiteral(node)) {
+        return true;
+    }
+
+    if (t.isTemplateLiteral(node)) {
+        return node.expressions.every(expr => isConstantExpression(expr as t.Node));
+    }
+
+    if (t.isUnaryExpression(node)) {
+        // Allow !, -, +, ~ on constant expressions
+        const allowedOps = new Set(['!', '-', '+', '~', 'void', 'typeof']);
+        return allowedOps.has(node.operator) && isConstantExpression(node.argument);
+    }
+
+    if (t.isBinaryExpression(node)) {
+        return isConstantExpression(node.left) && isConstantExpression(node.right);
+    }
+
+    if (t.isLogicalExpression(node)) {
+        return isConstantExpression(node.left) && isConstantExpression(node.right);
+    }
+
+    if (t.isConditionalExpression(node)) {
+        return (
+            isConstantExpression(node.test) &&
+            isConstantExpression(node.consequent) &&
+            isConstantExpression(node.alternate)
+        );
+    }
+
+    if (t.isArrayExpression(node)) {
+        return node.elements.every(el => el !== null && isConstantExpression(el));
+    }
+
+    if (t.isSequenceExpression(node)) {
+        return node.expressions.every(expr => isConstantExpression(expr));
+    }
+
+    if (t.isParenthesizedExpression && t.isParenthesizedExpression(node)) {
+        return isConstantExpression((node as any).expression);
+    }
+
+    // Identifiers, MemberExpressions, CallExpressions, etc. are NOT safe
+    return false;
+}

