+// Password utilities for Blink1Control2
+const crypto = require('crypto');
+
+const ALGORITHM = 'aes-256-gcm';
+const KEY_LEN = 32;
+const IV_LEN = 16;
+const SALT_LEN = 16;
+const ITERATIONS = 100000;
+const DIGEST = 'sha256';
+
+/**
+ * Encrypt password using AES-256-GCM with PBKDF2-derived key
+ */
+function encryptPassword(password) {
+    const salt = crypto.randomBytes(SALT_LEN);
+    const iv = crypto.randomBytes(IV_LEN);
+    const key = crypto.pbkdf2Sync(password, salt, ITERATIONS, KEY_LEN, DIGEST);
+    const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
+    const encrypted = Buffer.concat([cipher.update(password, 'utf8'), cipher.final()]);
+    const authTag = cipher.getAuthTag();
+    return Buffer.concat([salt, iv, authTag, encrypted]).toString('hex');
+}
+
+/**
+ * Hash password for storage using PBKDF2
+ */
+function hashPassword(password) {
+    const salt = crypto.randomBytes(SALT_LEN);
+    const hash = crypto.pbkdf2Sync(password, salt, ITERATIONS, KEY_LEN, DIGEST);
+    return salt.toString('hex') + ':' + hash.toString('hex');
+}
+
+/**
+ * Verify password against stored hash
+ */
+function verifyPassword(password, stored) {
+    const [saltHex, hashHex] = stored.split(':');
+    const salt = Buffer.from(saltHex, 'hex');
+    const hash = crypto.pbkdf2Sync(password, salt, ITERATIONS, KEY_LEN, DIGEST);
+    return crypto.timingSafeEqual(hash, Buffer.from(hashHex, 'hex'));
+}
+
+/**
+ * Store password hash in settings
+ */
+function storePassword(settings, password) {
+    settings.apiPassword = hashPassword(password);
+    return settings;
+}
+
+module.exports = { encryptPassword, hashPassword, verifyPassword, storePassword };

