+		description: 'Access to constructor is not allowed in expressions',
+	},
+	{
+		pattern: /__proto__/,
+		description: 'Access to __proto__ is not allowed in expressions',
+	},
+	{
+		pattern: /\bprototype\b/,
+		description: 'Access to prototype is not allowed in expressions',
+	},
+	{
+		pattern: /\bprocess\b/,
+		description: 'Access to process is not allowed in expressions',
+	},
