+		pattern: /\bglobalThis\b/,
+		description: 'Access to globalThis is not allowed in expressions',
+	},
+	{
+		pattern: /\brequire\b/,
+		description: 'Access to require is not allowed in expressions',
+	},
+	{
+		pattern: /\bimport\b/,
+		description: 'Dynamic import is not allowed in expressions',
+	},
+	{
+		pattern: /\beval\b/,
+		description: 'eval is not allowed in expressions',
+	},
+	{
+		pattern: /\bFunction\b/,
+		description: 'Function constructor is not allowed in expressions',
+	},
+	{
+		pattern: /\bsetTimeout\b|\bsetInterval\b|\bsetImmediate\b/,
+		description: 'Timer functions are not allowed in expressions',
+	},
+];
+
+/**
+ * Validates an expression string for dangerous patterns that could lead to
+ * sandbox escape or remote code execution.
+ *
+ * @throws {ExpressionError} if the expression contains dangerous patterns
+ */
+export function sanitizeExpression(expression: string): void {
+	for (const { pattern, description } of DANGEROUS_PATTERNS) {
+		if (pattern.test(expression)) {
+			throw new ExpressionError(description, {
+				description,
+				causeDetailed: `Expression contains blocked pattern: ${pattern.toString()}`,
+			});
+		}
+	}
+}
