@@ -0,0 +1,60 @@
+const dns = require('dns');
+const { getConfigValue } = require('../util');
+
+/**
+ * List of hostnames that are always considered valid for local access.
+ */
+const ALWAYS_ALLOWED_HOSTS = [
+    'localhost',
+    '127.0.0.1',
+    '::1',
+    '[::1]',
+];
+
+/**
+ * Middleware to prevent DNS rebinding attacks by validating the Host header.
+ * @param {import('express').Request} req
+ * @param {import('express').Response} res
+ * @param {import('express').NextFunction} next
+ */
+function hostHeaderMiddleware(req, res, next) {
+    // Skip check if whitelist is disabled
+    const whitelistEnabled = getConfigValue('whitelistMode', true);
+    if (!whitelistEnabled) {
+        return next();
+    }
+
+    const hostHeader = req.headers['host'];
+    if (!hostHeader) {
+        res.status(400).send('Bad Request: Missing Host header');
+        return;
+    }
+
+    // Strip port from host header
+    const host = hostHeader.replace(/:\d+$/, '').toLowerCase();
+
+    // Always allow loopback addresses
+    if (ALWAYS_ALLOWED_HOSTS.includes(host)) {
+        return next();
+    }
+
+    // Allow the configured listen address/hostname
+    const listenAddress = getConfigValue('listen', false);
+    const configuredHost = getConfigValue('hostname', '');
+
+    if (configuredHost && host === configuredHost.toLowerCase()) {
+        return next();
+    }
+
+    // Allow IP addresses (numeric) - they can't be rebound
+    const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/;
+    const ipv6Regex = /^\[?[0-9a-f:]+\]?$/i;
+    if (ipv4Regex.test(host) || ipv6Regex.test(host)) {
+        return next();
+    }
+
+    // Reject anything else - likely a DNS rebinding attempt
+    console.warn(`[Host Header Check] Rejected request with Host: ${hostHeader}`);
+    res.status(403).send('Forbidden: Invalid Host header. This may indicate a DNS rebinding attack.');
+}
+
+module.exports = { hostHeaderMiddleware };
